use slugs::slugify;

#[test]
fn punctuation_and_spaces_become_one_dash() {
    assert_eq!(slugify("Hello, World"), "hello-world");
}

use slugs::slugify;

#[test]
fn surrounding_spaces_leave_no_dash() {
    assert_eq!(slugify("  Rust  2024 "), "rust-2024");
}

use slugs::slugify;

#[test]
fn accents_become_their_base_letter() {
    assert_eq!(slugify("Crème brûlée"), "creme-brulee");
}

use slugs::slugify;

#[test]
fn long_titles_are_cut_at_a_word_boundary() {
    let title = "word ".repeat(24);
    assert_eq!(title.len(), 120);
    let slug = slugify(&title);
    assert!(slug.len() <= 60, "{} characters", slug.len());
    assert!(!slug.ends_with('-'));
}
